check:
{v:'VER',what:'cloud-coop-takeover-no-free-stronghold: after the host is gone, player 2 window pays STRONGHOLD CLEARED only for a stronghold whose defenders it held and killed, never for an open one rebuilt from the host word with no defenders of its own',
 run:function(){
   if(!(window.__state&&window.__endRaid&&window.__runPrep&&window.__topClear)) return 'SKIP: no raid here';
   if(typeof arcadeDeploy!=='function'||typeof netWorldSend!=='function'||typeof netHostGone!=='function'||typeof shTick!=='function'||typeof shOpen!=='function'||typeof flowTick!=='function') return 'SKIP: the co-op stronghold path is not here';
   var bad=[], g=null, NK={}, k, oSF=netSendFast, oS=netSend, oSay=say, said=[], sent=[], w=null, h={seat:0,state:'in'}, HF, PF, staged=false, s0=null, c0, i, j, n;
   function asHost(){ NET.role='host'; NET.seat=0; NET.peers=[{seat:1,state:'in'}]; NET.upSeed=g.seed>>>0; g.flow=HF; }
   function asTwo(){ NET.role='join'; NET.seat=1; NET.peers=[h]; NET.upSeed=g.seed>>>0; g.flow=PF; }
   function cleared(){ return said.filter(function(x){ return (/STRONGHOLD CLEARED/).test(x); }).length; }
   try{
     __topClear(); __runPrep();
     if(!arcadeDeploy({mapIx:0,seed:4242})) return 'SKIP: no arcade raid';
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     g.player.iv=99; g.player.armor=0;
     for(k in NET) NK[k]=NET[k];
     staged=true;
     NET.on=true; NET.max=4; NET.specG=null; NET.up=[]; NET.entMap={};
     netSendFast=function(qq,m){ sent.push(JSON.parse(JSON.stringify(m))); return true; };
     netSend=function(qq,m){ return true; };
     say=function(a,b,c){ said.push(String(a)+((c&&c.sub)?' / '+c.sub:'')); return oSay.apply(this,arguments); };
     HF=g.flow||{}; PF={};
     asHost(); g.t=260; flowTick(0.01);
     if(!HF.sh||!HF.sh.sites||!HF.sh.sites.length) return 'SKIP: no stronghold on this map';
     // the host breaches the first stronghold, its defenders still fighting
     shOpen(HF.sh.sites[0]);
     n=HF.sh.sites[0].def.concat(HF.sh.sites[0].def2).filter(shAlive).length;
     if(!(n>0)) return 'SKIP: the host stronghold has no live defenders';
     sent.length=0; netWorldSend();
     for(j=sent.length-1;j>=0;j--) if(sent[j].t==='wd'){ w=sent[j]; break; }
     if(!w) return 'SKIP: the host sent no world word';
     asTwo(); netOnMsg(h,JSON.stringify(w));
     for(i=0;PF.sh&&PF.sh.sites&&i<PF.sh.sites.length;i++) if(PF.sh.sites[i].i===HF.sh.sites[0].i) s0=PF.sh.sites[i];
     if(!s0||!s0.open) return 'player 2 window did not take the open stronghold from the word';
     // THE HOST WINDOW CLOSES: player 2 picks up the raid
     if(!netHostGone('out')) return 'SKIP: the takeover did not run';
     if(flowPeer()) bad.push('player 2 window still runs as a peer after the takeover');
     c0=ARCADE.mine|0; said.length=0;
     for(i=0;i<5;i++) shTick(0.1);
     if(s0.clear) bad.push('the open stronghold rebuilt from the host word was marked cleared with its defenders never killed');
     if(cleared()) bad.push('player 2 window said STRONGHOLD CLEARED for nothing ('+said.join(' ; ')+')');
     if((ARCADE.mine|0)!==c0) bad.push('player 2 window was paid '+((ARCADE.mine|0)-c0)+' for a stronghold nobody cleared');
     // control: a stronghold still closed at the takeover, breached and cleared from this window, still pays
     s0.open=0; s0.prog=0; s0.clear=0; s0.def=[]; s0.def2=[]; s0.cache=null;
     shOpen(s0);
     if(!(s0.def2&&s0.def2.length)) return 'SKIP: the control stronghold got no defenders';
     for(i=0;i<5;i++) shTick(0.1);
     if(s0.clear) bad.push('CONTROL: the stronghold cleared with its defenders alive');
     for(i=0;i<s0.def2.length;i++) s0.def2[i].hp=0;
     c0=ARCADE.mine|0; said.length=0;
     shTick(0.1);
     if(!s0.clear) bad.push('CONTROL: the stronghold breached from player 2 window was not cleared when its defenders died');
     if((ARCADE.mine|0)-c0!==SH.chip) bad.push('CONTROL: clearing it paid '+((ARCADE.mine|0)-c0)+' not '+SH.chip);
     if(!cleared()) bad.push('CONTROL: no STRONGHOLD CLEARED line');
   }catch(x2){ bad.push('threw: '+String(x2&&x2.message||x2)); }
   finally{
     netSendFast=oSF; netSend=oS; say=oSay;
     if(staged){ for(k in NET) if(!(k in NK)) delete NET[k]; for(k in NK) NET[k]=NK[k]; }
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
     __topClear();
   }
   return bad.length?bad.join(' | '):null;
 }},
